check_code:
syn={'Resolute':{'Determined','Firm','Steadfast'}}
opts={'A':'Wavering','B':'Thoughtful','C':'Dithering','D':'Determined'}
ok=[k for k,v in opts.items() if v in syn['Resolute']]
assert ok==['D']

opts={'A':(36,88,80),'B':(68,54,94),'C':(34,56,62),'D':(23,56,51)}
f=lambda t:t[0]+t[1]-t[2]
vals={k:f(v) for k,v in opts.items()}
odd=[k for k,v in vals.items() if list(vals.values()).count(v)==1]
assert odd==['A'] and len(set(vals.values()))==2

def enc(w): return ''.join(c if c in 'AEIOU' else chr(ord(c)-1) for c in w)
assert enc('CLERK')=='BKEQJ' and enc('OFFICE')=='OEEIBE'
opts={'A':'RSOO','B':'OORS','C':'OROS','D':'OSOR'}
assert [k for k,v in opts.items() if v==enc('POST')]==['B']

from fractions import Fraction as F
def ev(a,b):
    m={a:b,b:a}; g=lambda x:F(m.get(x,x))
    return g(15)+g(5)*g(8)-g(72)/g(4)+g(16)*g(3)
opts={'A':(15,16),'B':(5,4),'C':(8,4),'D':(5,3)}
assert [k for k,v in opts.items() if ev(*v)==101]==['D']

def f(w): return ''.join(chr(ord(w[i])+1) for i in (2,3,0,1))
assert f('EYES')=='FTFZ' and f('MIND')=='OENJ'
opts={'A':'STRE','B':'STSF','C':'TUFS','D':'TUSF'}
assert [k for k,v in opts.items() if v==f('REST')]==['D']

a=set('65432'); b=set('24596')
r=(a-b)
assert r=={'3'}
opts={'A':'9','B':'6','C':'2','D':'3'}
assert [k for k,v in opts.items() if {v}==r]==['D']
